  `protocol_id` bigint DEFAULT NULL,
  `attack_vector_id` bigint DEFAULT NULL,
  `test_type_id` bigint DEFAULT NULL,
  `severity_id` bigint DEFAULT NULL,
  `threat_id` bigint DEFAULT NULL,
  `action_test_case` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_scope_status` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `attack_path` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `test_steps` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `expected_output` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `attack_feasibility` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cia_impact` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `safety_impact` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `deleted_by` bigint DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  `test_case_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pre_condition` longtext COLLATE utf8mb4_unicode_ci,
  `impact` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `objective_id` (`objective_id`),
  KEY `protocol_id` (`protocol_id`),
  KEY `attack_vector_id` (`attack_vector_id`),
  KEY `test_type_id` (`test_type_id`),
  KEY `severity_id` (`severity_id`),
  KEY `threat_id` (`threat_id`),
  KEY `ix_test_cases_deleted_at` (`deleted_at`),
  KEY `ix_test_cases_created_by` (`created_by`),
  KEY `ix_test_cases_updated_by` (`updated_by`),
  KEY `ix_test_cases_deleted_by` (`deleted_by`),
  CONSTRAINT `test_cases_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `test_cases_ibfk_2` FOREIGN KEY (`objective_id`) REFERENCES `objectives` (`id`),
  CONSTRAINT `test_cases_ibfk_3` FOREIGN KEY (`protocol_id`) REFERENCES `protocols` (`id`),
  CONSTRAINT `test_cases_ibfk_4` FOREIGN KEY (`attack_vector_id`) REFERENCES `attack_vectors` (`id`),
  CONSTRAINT `test_cases_ibfk_5` FOREIGN KEY (`test_type_id`) REFERENCES `test_types` (`id`),
  CONSTRAINT `test_cases_ibfk_6` FOREIGN KEY (`severity_id`) REFERENCES `severities` (`id`),
  CONSTRAINT `test_cases_ibfk_7` FOREIGN KEY (`threat_id`) REFERENCES `threats` (`id`),
  CONSTRAINT `test_cases_ibfk_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `test_cases_ibfk_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `test_cases_ibfk_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=336 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
